pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address fuzzBaseToken, address fuzzNft, uint128 vBase, uint128 vNft, uint56 changeFee, uint16 feeRate, bytes32 merkleRoot, bool useOracle, bool payRoyalties) public {
        vm.assume(feeRate <= type(uint16).max);
        bool ok;
        try c.initialize(fuzzBaseToken, fuzzNft, vBase, vNft, changeFee, feeRate, merkleRoot, useOracle, payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        if (!ok) return;

        assertTrue(c.baseToken() == fuzzBaseToken);
    }
}
